// Generated by esquadro: do not edit. A number on the dashboard, with what
// it is about, and a chart of a report's rows.
import type { ReactNode } from "react"
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts"
import { Card } from "@/components/ui/card.tsx"

export function StatCard({ label, value, hint }: { label: string; value: ReactNode; hint?: ReactNode }) {
  return (
    <Card>
      <div className="text-sm text-muted-foreground">{label}</div>
      <div className="mt-1 text-3xl font-semibold">{value}</div>
      {hint && <div className="mt-1 text-sm text-muted-foreground">{hint}</div>}
    </Card>
  )
}

/** Bars of rows: x, the name of each; y, the number. */
export function BarsChart<T extends Record<string, unknown>>({ rows, x, y }: { rows: T[]; x: keyof T & string; y: keyof T & string }) {
  return (
    <div className="h-64 w-full">
      <ResponsiveContainer>
        <BarChart data={rows}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey={x as never} />
          <YAxis />
          <Tooltip />
          <Bar dataKey={y as never} fill="var(--color-primary)" />
        </BarChart>
      </ResponsiveContainer>
    </div>
  )
}
